changes.before:
function track(){
  const m=S.meta;
  if(!m.type||!m.duration||!m.approval) return null;
  if(m.prior==="yes" && m.unchanged==="yes" && filled(m.priorCitation)) return {key:"scan",title:"Equity scan may be sufficient",text:"A prior formal analysis exists and its results were integrated. Use the scan to confirm nothing material changed; if it did, run the full analysis."};
  const lasting = m.duration==="prolonged";
  const approval = m.approval!=="none";
  if(lasting && approval) return {key:"full",title:"Formal equity analysis required",text:"Lasting impact and approval at supervisor level or above. The completed analysis must accompany the action when it goes for approval."};
  if(["legislative","bill","budget","contract","policy"].includes(m.type)) return {key:"full",title:"Formal equity analysis expected",text:"This action type is a named use of the toolkit. Use the full review to examine the effects and confirm any required policy review paths."};
  return {key:"scan",title:"Equity scan likely sufficient",text:"Based on the selected answers, a lighter review may be useful. Confirm any remaining uncertainties and required review paths. Complete the steps at a lighter depth and keep the record; if the scope grows, upgrade to a full analysis."};
}

